import java.util.*;

class Guest{
    String name;
    Guest(String n){
        name = n;
    }
    void display(){
        System.out.println("Name: "+name);
    }
}

class RegisteredGuest extends Guest{
    String rt;
    RegisteredGuest(String n,String r){
        super(n);
        rt = r;
    }
    void display(){
        System.out.println("Name: "+name);
        System.out.println("Room Type: "+rt);
    }
}

class LoyaltyGuest extends RegisteredGuest{
    int nig;
    float dis;
    float bill;
    LoyaltyGuest(String n,String r,int ni,int di){
        super(n,r);
        nig = ni;
        dis = di;
    }
    void calculate(){
        int p;
        if(rt.isequal("Standard")){
            p = 1000;
        }
        else if(rt.isequal("Standard")){
            p = 2000;
        }
        else{
            p = 3500;
        }
        bill = nig*p;
        bill = (float)bill*(100-dis)/100;
    }
    void display(){
            System.out.println("Name: "+name);
            System.out.println("Room Type: "+rt);
            System.out.printf("Total Bill: %.1f",bill);
    }
}

public class Main{
    public static void main(String args[]){
        Scanner sc = new Scanner(System.in);
        String name = sc.nextLine();
        String rt = sc.nextLine();
        int nig = sc.nextInt();
        int d = sc.nextFloat();
        LoyaltyGuest l = new LoyaltyGuest(name,rt,nig,d);
        l.calculate();
        l.display();
    }
}

