public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        try {
            String name = sc.nextLine();
            String type = sc.nextLine();
            int nights = Integer.parseInt(sc.nextLine());
            double discount = Double.parseDouble(sc.nextLine());

            if (name.matches(".*\\d.*") ||
                (!type.equals("Standard") && !type.equals("Deluxe") && !type.equals("Suite")) ||
                nights <= 0 || discount < 0 || discount > 100) {
                System.out.println("Invalid Input");
                return;
            }

            LoyaltyGuest g = new LoyaltyGuest(name, type, nights, discount);
            g.calculateBill();
            g.displayDetails();

        } catch (Exception e) {
            System.out.println("Invalid Input");
        }
    }
}

